        else if (i === N - 1) m = 0;
        else m = (K[i + 1][j] - K[i - 1][j]) / (K[i + 1][0] - K[i - 1][0]);
        row.push(m);
      }
      M.push(row);
    }
  })();

  function ss(u) { return u * u * (3 - 2 * u); }
  function f(n) { return (Math.round(n * 100) / 100).toString(); }
  function $(id) { return document.getElementById(id); }

